using UnityEngine;

/// <summary>
/// 移动组件：封装 Rigidbody2D 操作与视线检测缓存。
///
/// 速度数据源：EnemyStats.PatrolSpeed / EnemyStats.ChaseSpeed
///             由状态机在调用 MoveTowardsPosition 时显式传入。
/// </summary>
[RequireComponent(typeof(Rigidbody2D))]
public class EnemyMovement : MonoBehaviour
{
    [Tooltip("全局敌人速度倍率（道具效果），1=正常，0.5=半速")]
    public static float GlobalSpeedMultiplier = 1f;

    private Rigidbody2D _rb;
    private float _nextSightCheckTime;
    private bool _cachedHasLineOfSight;
    private bool _wasInDetectionRange = false;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (_rb != null) _rb.freezeRotation = true;
    }

    public void Stop()
    {
        if (_rb != null) _rb.velocity = Vector2.zero;
    }

    /// <summary>
    /// 向目标位置移动。
    /// </summary>
    /// <param name="target">目标世界坐标</param>
    /// <param name="speed">移动速度</param>
    /// <param name="speedMultiplier">额外速度倍率（0~1），用于搜索等减速行为</param>
    public void MoveTowardsPosition(Vector2 target, float speed, float speedMultiplier = 1f)
    {
        if (_rb == null || speed <= 0f) return;
        Vector2 dir = (target - (Vector2)transform.position).normalized;
        _rb.velocity = dir * speed * speedMultiplier * GlobalSpeedMultiplier;
    }

    public void SetVelocity(Vector2 vel)
    {
        if (_rb == null) return;
        _rb.velocity = vel * GlobalSpeedMultiplier;
    }

    /// <summary>直接传送到目标位置</summary>
    public void Teleport(Vector2 targetPos)
    {
        if (_rb != null)
        {
            _rb.velocity = Vector2.zero;
            _rb.position = targetPos;
        }
        else
        {
            transform.position = targetPos;
        }
    }

    /// <summary>
    /// 带缓存的视线检测。
    /// </summary>
    public bool HasLineOfSight(Vector2 targetPosition, float detectionRange, float sightCheckInterval = 0.2f)
    {
        float sqrDistance = ((Vector2)transform.position - targetPosition).sqrMagnitude;
        bool inRange = sqrDistance <= detectionRange * detectionRange;

        if (!inRange)
        {
            _wasInDetectionRange = false;
            _cachedHasLineOfSight = false;
            return false;
        }

        if (!_wasInDetectionRange)
        {
            _nextSightCheckTime = 0f;
            _wasInDetectionRange = true;
        }

        if (Time.time >= _nextSightCheckTime)
        {
            _nextSightCheckTime = Time.time + sightCheckInterval;
            RaycastHit2D hit = Physics2D.Linecast(transform.position, targetPosition);
            _cachedHasLineOfSight = hit.collider == null || !hit.collider.CompareTag("Wall");
        }

        return _cachedHasLineOfSight;
    }
}

using System;
using UnityEngine;

/// <summary>
/// 轻量状态机组件：管理当前状态的切换和每帧 Tick 调用。
/// 状态对象由外部创建并传入 ChangeState。
/// </summary>
public class EnemyStateMachine : MonoBehaviour
{
    public EnemyStateBase CurrentState { get; private set; }

    /// <summary>状态变更事件：参数 (oldState, newState)</summary>
    public event Action<EnemyStateBase, EnemyStateBase> OnStateChanged;//暂时没用，留给之后设计动画切换，音效，ui指示器之类的

    public void ChangeState(EnemyStateBase newState)
    {
        if (CurrentState != null)
            CurrentState.Exit();

        var old = CurrentState;
        CurrentState = newState;

        if (CurrentState != null)
            CurrentState.Enter();

        OnStateChanged?.Invoke(old, CurrentState);
    }

    private void Update()
    {
        CurrentState?.Tick();
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 碰撞伤害直接在此处理（OnTriggerStay2D + OnCollisionStay2D）。
/// 所有数值属性来源：EnemyStats（类似 PlayerStats 的单一数据源）。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    [Header("动画（可选，留空则从 config displayName 自动查找）")]
    [Tooltip("AnimatorController 资产路径（Assets/ 开始），留空则按敌人名自动查找")]
    [SerializeField] private string _animatorControllerPath = "";

    // 子组件
    public EnemyStats Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances =>
        SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    /// <summary>全局静态事件 — 任意敌人死亡时触发 (EnemyCore)</summary>
    public static event Action<EnemyCore> OnAnyEnemyDied;

    /// <summary>全局静态事件 — 任意敌人生成时触发 (EnemyCore)</summary>
    public static event Action<EnemyCore> OnAnyEnemySpawned;

    /// <summary>全局静态事件 — 任意敌人接触伤害命中时触发 (enemy, hitTarget)</summary>
    public static event Action<EnemyCore, GameObject> OnAnyContactHit;

    /// <summary>玩家碰撞伤害减免乘区（细胞骨架），1=正常，0.7=减免30%</summary>
    public static float PlayerCollisionReductionFactor = 1f;

    // 碰撞伤害冷却
    private float _lastContactDamageTime = -10f;
    private Animator _animator;
    private SpriteRenderer _spriteRenderer;

    private void Awake()
    {
        Health       = GetComponent<EnemyStats>();
        Movement     = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();

        if (Health       == null) Health       = gameObject.AddComponent<EnemyStats>();
        if (Movement     == null) Movement     = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        _animator = GetComponent<Animator>();
        _spriteRenderer = GetComponent<SpriteRenderer>();

        // 运行时 fallback：若 Animator 缺少 controller，按敌人名自动加载
        if (_animator != null && _animator.runtimeAnimatorController == null && config != null)
        {
            string enemyName = config.displayName;
            string autoPath = "Assets/Animations/Enemy/" + enemyName + "/" + enemyName + "_Controller.controller";
#if UNITY_EDITOR
            var ctrl = UnityEditor.AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(autoPath);
            if (ctrl != null)
            {
                _animator.runtimeAnimatorController = ctrl;
            }
            else
            {
                Debug.LogWarning("[EnemyCore] AnimatorController not found at: " + autoPath);
            }
#else
            // 非 Editor 环境需将 controller 放入 Resources 文件夹
            var ctrl = Resources.Load<RuntimeAnimatorController>(enemyName + "_Controller");
            if (ctrl != null)
                _animator.runtimeAnimatorController = ctrl;
#endif
        }

        // 技能释放 → 触发释放动画
        if (SkillManager != null)
        {
            SkillManager.OnSkillCast += (_, _) =>
            {
                if (_animator != null && HasAnimatorParameter("IsCasting"))
                {
                    _animator.SetBool("IsCasting", true);
                    StartCoroutine(ResetCastBool(1.4f));
                }
            };
        }

        // ═══ 单一数据源：EnemyConfig → EnemyStats（全部属性） ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth             = config.maxHealth;
                Health.PatrolSpeed           = config.patrolSpeed;
                Health.ChaseSpeed            = config.chaseSpeed;
                Health.DetectionRange        = config.detectionRange;
                Health.AttackRange           = config.attackRange;
                Health.ContactDamage         = config.contactDamage;
                Health.ContactDamageCooldown = config.contactDamageCooldown;
                Health.Initialize();
            }

            if (SkillManager != null)
            {
                // 固定技能列表优先：按 ID 精确装配；否则从技能库随机抽取
                if (config.fixedSkillIds != null && config.fixedSkillIds.Count > 0)
                    SkillManager.LoadSkills(config.skillLibrary, config.fixedSkillIds.ToArray());
                else
                    SkillManager.InitializeFromLibrary(config.skillLibrary);

                // 被动技能（永久光环等）在装配后自动执行一次
                SkillManager.AutoCastPassives(this);
            }
        }
        else if (Health != null)
        {
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                OnAnyEnemyDied?.Invoke(this);
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }

        // 广播生成事件
        OnAnyEnemySpawned?.Invoke(this);
    }

    private void Start()
    {
        StartCoroutine(TargetRefreshRoutine());

        // 启动默认状态
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    /// <summary>
    /// 周期性动态索敌：初始查找玩家后，每 0.3s 扫描检测范围内最近的 "Player" 标签目标（含随从）。
    /// 死亡或同化后自动停止。
    /// </summary>
    private System.Collections.IEnumerator TargetRefreshRoutine()
    {
        // Phase 1: 初始查找（同原 LazyFindPlayer 逻辑）
        while (PlayerTarget == null)
        {
            if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
                PlayerTarget = PlayerManager.Instance.CurrentPlayer.transform;
            else
                PlayerTarget = GameObject.FindGameObjectWithTag("Player")?.transform;

            yield return new WaitForSeconds(0.3f);
        }

        // Phase 2: 周期性动态刷新 — 扫描最近的 "Player" 标签目标（含随从）
        while (true)
        {
            yield return new WaitForSeconds(0.3f);
            if (IsDead || IsAssimilated) yield break;

            Transform nearest = FindNearestPlayerTarget();
            if (nearest != null)
                PlayerTarget = nearest;
        }
    }

    /// <summary>
    /// 在检测范围内查找最近的 "Player" 标签目标（含真实玩家和随从）。
    /// 死亡随从的 Collider 已禁用，OverlapCircleAll 自然跳过。
    /// </summary>
    private Transform FindNearestPlayerTarget()
    {
        if (Health == null) return null;

        Vector2 center = transform.position;
        float range = Health.DetectionRange;

        Collider2D[] hits = Physics2D.OverlapCircleAll(center, range);
        Transform best = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Player")) continue;
            if (hit.transform == transform) continue;

            // 跳过死亡的敌人/随从（Collider 已禁用，此为双保险）
            var core = hit.GetComponent<EnemyCore>();
            if (core != null && core.IsDead) continue;

            float d = ((Vector2)hit.transform.position - center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                best = hit.transform;
            }
        }

        return best;
    }

    private System.Collections.IEnumerator ResetCastBool(float delay)
    {
        yield return new WaitForSeconds(delay);
        if (_animator != null && HasAnimatorParameter("IsCasting"))
            _animator.SetBool("IsCasting", false);
    }

    /// <summary>检查 Animator 是否包含指定参数（避免 SetBool 报 "Parameter does not exist"）</summary>
    private bool HasAnimatorParameter(string paramName)
    {
        if (_animator == null || _animator.parameters == null) return false;
        foreach (var p in _animator.parameters)
            if (p.name == paramName) return true;
        return false;
    }

    // ---------- 朝向 ----------
    private void LateUpdate()
    {
        if (IsDead || _spriteRenderer == null || PlayerTarget == null) return;

        // 施法期间也允许翻转，始终跟随玩家方向
        float dx = PlayerTarget.position.x - transform.position.x;
        if (Mathf.Abs(dx) > 0.1f)
            _spriteRenderer.flipX = dx < 0f;
    }

    // ---------- 碰撞伤害 ----------

    private void OnTriggerStay2D(Collider2D other)
    {
        ProcessContactDamage(other.gameObject);
    }

    private void OnCollisionStay2D(Collision2D collision)
    {
        ProcessContactDamage(collision.gameObject);
    }

    private void ProcessContactDamage(GameObject other)
    {
        if (IsDead || Health == null) return;

        string targetTag = IsAssimilated ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        if (Time.time < _lastContactDamageTime + Health.ContactDamageCooldown) return;

        // 护盾拦截
        var shield = other.GetComponent<KeratinShieldRuntime>();
        if (shield != null && shield.IsActive)
        {
            shield.TryBlock();
            _lastContactDamageTime = Time.time;
            return;
        }

        // 碰撞免疫
        var playerStats = other.GetComponent<PlayerStats>();
        if (playerStats != null && playerStats.ImmuneToContactDamage) return;

        float dmg = Health.ContactDamage;

        // 细胞骨架：非随从（敌人）对玩家的碰撞伤害减免
        if (!IsAssimilated && PlayerCollisionReductionFactor < 1f)
            dmg *= PlayerCollisionReductionFactor;

        // 干扰素：随从攻击命中时给目标减速
        if (IsAssimilated && EnemyFollower.ApplySlow && other.CompareTag("Enemy"))
        {
            var slow = other.GetComponent<SlowEffect>();
            if (slow == null)
                slow = other.AddComponent<SlowEffect>();
            slow.Apply(EnemyFollower.SlowFactor, EnemyFollower.SlowDuration);
        }

        var damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(dmg);
            _lastContactDamageTime = Time.time;

            // 广播接触命中事件（供 OnContactHitBuff 等效果使用）
            OnAnyContactHit?.Invoke(this, other.gameObject);
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        return Health != null ? Health.ContactDamage : 10f;
    }

    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    public float GetSkillDamageModifier() => 1f;

    // ---------- 同化 ----------
    public void Assimilate(Transform playerTarget)
    {
        IsAssimilated = true;

        if (Health != null)
            Health.ClearOnDied();

        OnAssimilated?.Invoke(this);

        gameObject.tag = "Player";

        if (StateMachine != null)
        {
            StateMachine.ChangeState(null);
            StateMachine.enabled = false;
        }

        Movement?.Stop();

        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        PlayerTarget = playerTarget;
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI。
/// AI 决策由 FollowerStateMachine 驱动（Idle/Follow/Chase/Attack 四状态）。
/// 生命周期管理（传送/复活/跨场景/进化buff/道具增强）保留在本组件中。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 3.5f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 15f;

    [Header("复活")]
    [Tooltip("死亡后复活延迟（秒）")]
    [SerializeField] private float _respawnDelay = 10f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private EnemySkillManager _skillManager;
    private bool _isActive;
    private bool _isReviving;
    private bool _isPaused;
    private FollowerStateMachine _followerSM;

    // 进化倾向 buff：记录原始属性，动态刷新时从原始值重算
    private float _origMaxHealth, _origPatrolSpeed, _origChaseSpeed;
    private float _origDetectionRange, _origAttackRange, _origContactDamage, _origContactDamageCooldown;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    // ── 道具增强（静态，影响所有随从）──
    /// <summary>随从生命上限乘区（免疫球蛋白）</summary>
    public static float MaxHealthMultiplier = 1f;
    /// <summary>随从伤害乘区（集落刺激因子 CSF）</summary>
    public static float DamageMultiplier = 1f;
    /// <summary>随从技能冷却乘区（白细胞介素-2 IL-2）</summary>
    public static float FollowerCooldownFactor = 1f;
    /// <summary>随从攻击是否附带减速（干扰素）</summary>
    public static bool ApplySlow = false;
    /// <summary>减速比例（干扰素），0.8 = 减速20%</summary>
    public static float SlowFactor = 0.8f;
    /// <summary>减速持续时间（秒）</summary>
    public static float SlowDuration = 2f;
    /// <summary>随从数量上限（胸腺肽），默认4</summary>
    public static int MaxFollowerCount = 4;

    // ── 暴露给状态机的只读属性 ──
    public EnemyCore Core => _core;
    public EnemyMovement Movement => _movement;
    public EnemySkillManager SkillManager => _skillManager;
    public Transform Player => _player;
    public FollowerStateMachine StateMachine => _followerSM;
    public float FollowDistance => _followDistance;
    public float DetectionRange => _detectionRange;
    public float AttackRange => _attackRange;
    public float FollowSpeed => _followSpeed;

    /// <summary>随从是否处于活跃状态（未被暂停）</summary>
    public bool IsActive => _isActive && !_isPaused;

    /// <summary>暂停/恢复随从 AI（不改变 _isActive，用于陷阱等临时暂停）</summary>
    public void SetPaused(bool paused)
    {
        _isPaused = paused;
        if (paused) _movement?.Stop();
    }

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _skillManager = _core.SkillManager;

        // 记录原始属性，用于进化倾向 buff 重算
        if (_core.Health != null)
        {
            _origMaxHealth = _core.Health.MaxHealth;
            _origPatrolSpeed = _core.Health.PatrolSpeed;
            _origChaseSpeed = _core.Health.ChaseSpeed;
            _origDetectionRange = _core.Health.DetectionRange;
            _origAttackRange = _core.Health.AttackRange;
            _origContactDamage = _core.Health.ContactDamage;
            _origContactDamageCooldown = _core.Health.ContactDamageCooldown;

            // 应用当前进化倾向 buff
            ApplyEvolutionBuff();

            _core.Health.OnDied += HandleDeath;
        }

        // 先脱离房间父节点，再标记 DontDestroyOnLoad（对有父节点的子对象直接调用不生效）
        transform.SetParent(null);
        DontDestroyOnLoad(gameObject);

        // 创建随从状态机并启动
        _followerSM = new FollowerStateMachine();
        _followerSM.ChangeState(new FollowerIdleState(this));
    }

    /// <summary>根据玩家进化倾向刷新随从全属性增幅（叠加道具乘区）</summary>
    public void ApplyEvolutionBuff()
    {
        if (_core?.Health == null || !_isActive) return;

        var playerStats = _player?.GetComponent<PlayerStats>();
        if (playerStats == null) return;

        float tendency = playerStats.EvolutionTendency;
        float factor = playerStats.EvolveFollowerBuffFactor;
        float mult = Mathf.Max(0f, 1f + (-tendency) * factor);

        _core.Health.MaxHealth = Mathf.Max(_origMaxHealth * mult * MaxHealthMultiplier, 1f);
        _core.Health.PatrolSpeed = _origPatrolSpeed * mult;
        _core.Health.ChaseSpeed = _origChaseSpeed * mult;
        _core.Health.DetectionRange = _origDetectionRange * mult;
        _core.Health.AttackRange = _origAttackRange * mult;
        _core.Health.ContactDamage = _origContactDamage * mult * DamageMultiplier;
        _core.Health.ContactDamageCooldown = _origContactDamageCooldown * mult;

        // 应用随从技能冷却乘区
        if (_skillManager != null)
        {
            foreach (var s in _skillManager.SkillInstances)
                s.CooldownFactor = FollowerCooldownFactor;
        }
    }

    /// <summary>刷新所有活跃随从的进化倾向 buff（由 PlayerStats 在倾向值变化时调用）</summary>
    public static void RefreshAllFollowers(float tendency, float factor)
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    /// <summary>刷新所有活跃随从（道具增强变化时调用）</summary>
    public static void RefreshAllFollowers()
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    private void Update()
    {
        if (!_isActive || _isPaused || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = ((Vector2)transform.position - (Vector2)_player.position).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(_player.position);
            return;
        }

        _followerSM?.Tick();
    }

    /// <summary>在检测范围内查找最近的 "Enemy" 标签目标</summary>
    public Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        // 随从传送由 MapManager.TeleportFollowers 统一处理（在玩家传送到新房间之后）
    }

    private void HandleDeath()
    {
        _isActive = false;
        _isReviving = true;

        // 停止状态机
        _followerSM?.ChangeState(null);

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();

        // 隐藏视觉
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = false;

        StartCoroutine(RespawnRoutine());
    }

    private IEnumerator RespawnRoutine()
    {
        yield return new WaitForSeconds(_respawnDelay);

        // 复活
        if (_core?.Health != null)
        {
            _core.Health.Revive();
            ApplyEvolutionBuff();
        }

        // 传送到玩家身边
        if (_player != null)
            _movement?.Teleport(_player.position);

        // 恢复视觉和碰撞
        foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            sr.enabled = true;
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = true;

        _isActive = true;
        _isReviving = false;

        // 重启状态机
        _followerSM?.ChangeState(new FollowerIdleState(this));
    }

    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        if (scene.name == "Start" || scene.name == "Result" || scene.name == "Winning")
        {
            Destroy(gameObject);
            return;
        }

        // 游戏场景：重新查找玩家引用
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            _player = PlayerManager.Instance.CurrentPlayer.transform;
        else
            _player = GameObject.FindGameObjectWithTag("Player")?.transform;

        // 传送到玩家身边（防止随从出现在旧位置）
        if (_player != null && _movement != null && !_isReviving)
            _movement.Teleport(_player.position);
    }
}

