/// 发现玩家 → ChaseState。
/// </summary>
public class PatrolState : EnemyStateBase
{
    private int _currentIndex;
    private float _waitTimer;
    private static readonly float WaitPerPoint = 0.8f;
    private static readonly float ArriveThreshold = 0.3f;

    public PatrolState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _currentIndex = 0;
        _waitTimer   = 0f;
    }

    public override void Tick()
    {
        if (Core.PlayerTarget != null && Core.Health != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        var pts = Core.config != null ? Core.config.patrolPoints : null;
        if (pts == null || pts.Count == 0)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 target = pts[_currentIndex];
        float sqrDist = ((Vector2)Core.transform.position - target).sqrMagnitude;

        if (sqrDist < ArriveThreshold * ArriveThreshold)
        {
            Core.Movement?.Stop();
            _waitTimer += Time.deltaTime;
            if (_waitTimer >= WaitPerPoint)
            {
                _waitTimer = 0f;
                _currentIndex = (_currentIndex + 1) % pts.Count;
            }
        }
        else
        {
            _waitTimer = 0f;
            Core.Movement?.MoveTowardsPosition(target, Core.Health.PatrolSpeed);
        }
    }
}

using UnityEngine;

/// <summary>
/// 追击状态：高速追向玩家。
/// 脱战距离 = 3× detectionRange，短暂失去视线切 SearchState。
/// 进入攻击范围 → AttackState。
/// </summary>
public class ChaseState : EnemyStateBase
{
    public ChaseState(EnemyCore core) : base(core) { }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.Health == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float attackSqr = Core.Health.AttackRange * Core.Health.AttackRange;

        // 脱战判定：3× detectionRange
        float leashRange = Core.Health.DetectionRange * 3f;
        if (sqrDist > leashRange * leashRange)
        {
            Core.Movement?.Stop();
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        // 视线检测
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.Health.DetectionRange);
        if (!canSee)
        {
            Core.StateMachine.ChangeState(new SearchState(Core));
            return;
        }

        Core.LastKnownPlayerPosition = playerPos;

        // 轴向喷射型敌人（结核分枝杆菌）：进入攻击范围即进入喷射状态（沿三个固定角发射），而非继续追击
        if (Core.config != null && Core.config.useAxialSpray)
        {
            if (sqrDist <= attackSqr)
            {
                Core.StateMachine.ChangeState(new AxialSprayState(Core));
                return;
            }
        }

        // 进入攻击范围
        if (sqrDist <= attackSqr)
        {
            Core.StateMachine.ChangeState(new AttackState(Core));
            return;
        }

        // 追击
        Core.Movement?.MoveTowardsPosition(playerPos, Core.Health.ChaseSpeed);
    }
}

